import { Address, address } from '@solana/kit';

export const SLOTS_PER_MINUTE = (60 * 1000) / 400;

export const DEFAULT_TIMEOUT_MS = 700;

// Single source of truth for all supported router types
export const SUPPORTED_ROUTER_TYPES = [
  'okx',
  'jupiter',
  'per',
  'dflow',
  'fluxbeam',
  'raydium',
  'autobahn',
  'jupiterU',
  'jupiterZ',
  'hashflow',
  'jupiterLite', // Jupiter Lite is always using the lite jupiter api - should be used for BE redundancy in case our api is down
  'jupiterSelfHosted',
  'jupiterEuropa',
  'clover',
  'openOcean',
  'spur',
  'zeroEx', // "0x", but prefer all letters because identifiers cannot start with a number and "0x" is also prefix for hex numbers
  'lifi',
] as const;

/**
 * Non-composable routers do not allow ixs to be added to the transaction
 * Typically the response will only contain a transaction, not an ixsRouter field, or the ixsRouter field contains only supplemental ixs
 */
export const NON_COMPOSABLE_ROUTERS: RouterType[] = [
  'per', // no ixsRouter field, only a transaction
  'hashflow', // ixsRouter field only contains supplemental ixs
];

/**
 * Routers that support the `preferredMaxAccounts` parameter
 * These routers can optimize for fewer accounts when requested
 */
export const PREFERRED_MAX_ACCOUNT_SUPPORTED_ROUTERS: RouterType[] = [
  'autobahn',
  'openOcean',
  'jupiter',
  'jupiterSelfHosted',
  'jupiterEuropa',
  'jupiterLite',
  'zeroEx',
];

// Single source of truth for all supported router types
export const CLOVER_DEX_TYPES = ['limo', 'exponent'] as const;

export type CloverDexType = (typeof CLOVER_DEX_TYPES)[number];

export const RFQ_ROUTERS: RouterType[] = ['per', 'hashflow', 'jupiterZ'];

export const EXCLUDED_QUOTES_ROUTERS = ['fluxbeam'];

// bogdan: do we need incremental IDs? Using the public keys seems simpler and more consistent
export const ROUTER_TYPE_IDS = {
  okx: 1,
  jupiter: 2,
  per: 3,
  dflow: 4,
  fluxbeam: 5,
  raydium: 6,
  autobahn: 7,
  jupiterU: 8,
  jupiterZ: 9,
  hashflow: 10,
  jupiterLite: 11,
  jupiterSelfHosted: 12,
  clover: 13,
  openOcean: 14,
  spur: 15,
  zeroEx: 16,
  lifi: 17,
  jupiterEuropa: 18,
} as const;

// Type that represents the router ID values
export type RouterTypeID = (typeof ROUTER_TYPE_IDS)[RouterType];

// Utility functions to convert between types and IDs
export function getRouterTypeID(routerType: RouterType): RouterTypeID {
  return ROUTER_TYPE_IDS[routerType];
}

export function getAllRouterTypeIDsMap() {
  const mapping = ROUTER_TYPE_IDS;

  return { mapping };
}

// Define RouterType directly from the constant
export type RouterType = (typeof SUPPORTED_ROUTER_TYPES)[number];

// Helper function to check if a string is a valid router type
export function isValidRouterType(type: string): type is RouterType {
  return SUPPORTED_ROUTER_TYPES.includes(type as RouterType);
}

