// 1. Add it to SUPPORTED_ROUTER_TYPES in consts.ts (SDK and API)
// 2. Add the program ID here in ROUTER_PROGRAM_IDS

// Dynamically create the map using SUPPORTED_ROUTER_TYPES to ensure all are present
export const ROUTER_PROGRAM_MAP = Object.fromEntries(
  SUPPORTED_ROUTER_TYPES.map((router) => [router, ROUTER_PROGRAM_IDS[router]]),
) as Record<RouterType, Address>;

// Extract the value types from the mapping
export type RouterSwapProgram = (typeof ROUTER_PROGRAM_MAP)[RouterType];

